class C
{
    static void M()
    {
        var x = ("Alice", "Bob");
        System.Console.WriteLine($"{x.Item1}");
    }
}

namespace System
{
    public struct ValueTuple<T1, T2>
    {
        public string Item1; // Not T1
        public int Item2;

        public ValueTuple(T1 item1, T2 item2)
        {
            this.Item1 = "1";
            this.Item2 = 2;
        }

        (T1, T2) M1() => throw null;
        (T1 a, T2 b) M2() => throw null;
    }
}

